import sys, json, re
content = sys.stdin.read()
# Find the JSON object in the content
match = re.search(r'\{.*\}', content, re.DOTALL)
if match:
    data = json.loads(match.group())
    json.dump(data, open('baseline-packages.json','w'), indent=2)
    for proj in data.get('projects', []):
        path = proj.get('path','').split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                print(f\"{path} | {fw['framework']} | {pkg['id']} | requested={pkg.get('requestedVersion','')} resolved={pkg.get('resolvedVersion','')}\")
else:
    print('No JSON found')
" 2>&1 || echo "baseline parse failed"

